function drawProjectile(q){ctx.save();ctx.translate(q.x,q.y);ctx.scale(q.face,1);const c=q.kind==='spider'?'#ff3e70':q.kind==='captain'?'#45c8ff':q.kind==='panther'?'#a1f4ff':'#ffb43d';ctx.shadowColor=c;ctx.shadowBlur=23;ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(0,0,26,13,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.ellipse(5,0,11,6,0,0,Math.PI*2);ctx.fill();ctx.restore()}
function draw(){ctx.clearRect(0,0,W,H);ctx.save();if(shake>0){ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);shake=Math.max(0,shake-0.8)}bg();for(const q of projectiles)drawProjectile(q);drawFighter(p);drawFighter(e);ctx.restore();}
function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);
const map={a:'left',arrowleft:'left',d:'right',arrowright:'right',w:'jump',arrowup:'jump',j:'light',k:'heavy',l:'special',shift:'block'};
window.addEventListener('keydown',ev=>{const k=map[ev.key.toLowerCase()];if(!k)return;ev.preventDefault();if(!ev.repeat)inputAction(k,true)});window.addEventListener('keyup',ev=>{const k=map[ev.key.toLowerCase()];if(k)inputAction(k,false)});window.addEventListener('blur',()=>{keys.left=keys.right=keys.block=false;p.block=false});
document.querySelectorAll('.control-btn').forEach(btn=>{const k=btn.dataset.key;if(!k)return;const down=ev=>{ev.preventDefault();btn.classList.add('pressed');inputAction(k,true)};const up=ev=>{ev.preventDefault();btn.classList.remove('pressed');inputAction(k,false)};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('pointerleave',up)});
canvas.addEventListener('pointerdown',()=>{if(!running)start()});updateHUD();
})();
</script>
</body>
</html>

